// «Performance турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

let loaderCalls = 0;
function loader(ids) {
  loaderCalls = loaderCalls + 1;
  return ids.map((id) => ({ id: id, name: "Хэрэглэгч " + id }));
}

window.RESULT = batchGet([1, 2, 2, 3], loader);
window.LOADER_CALLS = loaderCalls;

panel("ok", "res", "Багц ачаалалт", ["loader дуудлага: " + window.LOADER_CALLS, JSON.stringify(window.RESULT, null, 2)]);
document.body.dataset.ready = "1";

